void PointTemplateBase::RotateAround( PointTemplateBase& rPoint,
                          Degree10 nOrientation ) const
{
    tools::Long nX = rPoint.mnA;
    tools::Long nY = rPoint.mnB;
    RotateAround(nX, nY, nOrientation);
    rPoint.mnA = nX;
    rPoint.mnB = nY;
